mapper.select:
select  
where c.del_flag = '0'
and c.certificate_id = #{certificateId}
and c.review_status = #{reviewStatus}
and u.dept_id = #{currentDeptId}
and c.current_flag = 'Y' and c.expires_on < current_date()
and c.current_flag = 'Y' and c.expires_on between current_date() and date_add(current_date(), interval 30 day)
and c.current_flag = 'Y' and c.review_status = 'APPROVED' and c.expires_on <= date_add(current_date(), interval 30 day)
${params.dataScope}
order by case c.review_status when 'PENDING_REVIEW' then 0 else 1 end,
         c.expires_on, c.certificate_id desc

select  
where c.del_flag = '0' and c.review_status = 'APPROVED'
  and c.current_flag = 'Y' and c.expires_on <= #{expiresThrough}
  and c.certificate_id > #{afterCertificateId}
  and (p.employee_status is null or p.employee_status <> '离职')
order by c.certificate_id
limit #{limit}
